{
  "items": [
    {
      "name": "IsAdjoinRootMonic.map_modByMonic",
      "module_name": "Mathlib.RingTheory.IsAdjoinRoot",
      "kind": "theorem",
      "type": "∀ {R : Type u} {S : Type v} [inst : CommRing R] [inst_1 : Ring S] {f : Polynomial R} [inst_2 : Algebra R S]\n  (h : IsAdjoinRootMonic S f) (g : Polynomial R), h.map (g %ₘ f) = h.map g"
    },
    {
      "name": "Polynomial.eval₂_modByMonic_eq_self_of_root",
      "module_name": "Mathlib.Algebra.Polynomial.Div",
      "kind": "theorem",
      "type": "∀ {R : Type u} {S : Type v} [inst : CommRing R] [inst_1 : CommRing S] {f : R →+* S} {p q : Polynomial R},\n  q.Monic → ∀ {x : S}, Polynomial.eval₂ f x q = 0 → Polynomial.eval₂ f x (p %ₘ q) = Polynomial.eval₂ f x p"
    },
    {
      "name": "Polynomial.aeval_modByMonic_eq_self_of_root",
      "module_name": "Mathlib.Algebra.Polynomial.RingDivision",
      "kind": "theorem",
      "type": "∀ {R : Type u} {S : Type v} [inst : CommRing R] [inst_1 : Ring S] [inst_2 : Algebra R S] {p q : Polynomial R},\n  q.Monic → ∀ {x : S}, (Polynomial.aeval x) q = 0 → (Polynomial.aeval x) (p %ₘ q) = (Polynomial.aeval x) p"
    },
    {
      "name": "SModEq.eval",
      "module_name": "Mathlib.LinearAlgebra.SModEq.Basic",
      "kind": "theorem",
      "type": "∀ {R : Type u_6} [inst : CommRing R] {I : Ideal R} {x y : R},\n  x ≡ y [SMOD I] → ∀ (f : Polynomial R), Polynomial.eval x f ≡ Polynomial.eval y f [SMOD I]"
    },
    {
      "name": "Polynomial.modByMonic_eq_of_dvd_sub",
      "module_name": "Mathlib.Algebra.Polynomial.Div",
      "kind": "theorem",
      "type": "∀ {R : Type u} [inst : CommRing R] {p₁ p₂ q : Polynomial R}, q.Monic → q ∣ p₁ - p₂ → p₁ %ₘ q = p₂ %ₘ q"
    },
    {
      "name": "Polynomial.modByMonic_X_sub_C_eq_C_eval",
      "module_name": "Mathlib.Algebra.Polynomial.Div",
      "kind": "theorem",
      "type": "∀ {R : Type u} [inst : CommRing R] (p : Polynomial R) (a : R),\n  p %ₘ (Polynomial.X - Polynomial.C a) = Polynomial.C (Polynomial.eval a p)"
    }
  ]
}
